guardrail.good:
def method_missing(name, *args)
  if name.to_s.start_with?("find_by_")
    find_by_attribute(name.to_s.delete_prefix("find_by_"), args.first)
  else
    super
  end
end

def respond_to_missing?(name, include_private = false)
  name.to_s.start_with?("find_by_") || super
end

guardrail.bad:
def serialize(obj)
  obj.to_h  # may raise NoMethodError deep inside — hard to debug
end

def each(&block)
  items.each { |i| block.call(i) }  # unnecessary explicit block object
end

testing.pattern:
# frozen_string_literal: true
RSpec.describe PaymentService do subject(:service) { described_class.new(gateway: gateway) }
let(:gateway) { instance_double(PaymentGateway) } let(:account) { build(:account, balance: 100.0) }
describe "#charge" do context "when account has sufficient funds" do before { allow(gateway).to receive(:process).and_return(true) }
it "debits the account" do expect { service.charge(account, 50.0) } .to change { account.balance }.from(100.0).to(50.0) end end
context "when account has insufficient funds" do it "raises InsufficientFundsError" do expect { service.charge(account, 200.0) } .to raise_error(InsufficientFundsError, /needs 200/) end end end end

FactoryBot.define do
  factory :user do
    sequence(:email) { |n| "user#{n}@example.com" }
    name  { "Test User" }
    active { true }

    trait(:admin)    { role { "admin" } }
    trait(:inactive) { active { false } }
  end
end
